export function providerIconSvg(provider, options = {}) {
    const icon = resolveProviderIcon(provider, options);
    const prefix = options.prefix ?? 'ad-icon';
    if (!icon || !/^[A-Za-z][A-Za-z0-9_-]{0,100}$/.test(prefix)) return undefined;
    return svg[icon.file].replaceAll('__AD_ICON__', prefix + '-');
}
